  'prefs.ui3.a67715377961': 'FileVault protects the simulated home folder on this web Mac. It does not change or encrypt any files on your real Mac.',
  'prefs.ui3.47cc0aa30cd8': 'This browser does not provide Web Bluetooth; use Chromium over a secure origin.',
  'prefs.ui3.37581407b6e0': 'FileVault secures your home folder with your login password. This web edition does not encrypt real files.',
  'prefs.ui3.b1c21819f415': 'Write down the recovery hint. If you forget your login password, use the hint to identify this simulated vault.',
