  'app.ln3.8fcc33f5f280': 'In Leopard, Finder adds Cover Flow, Quick Look, a redesigned sidebar, and local network share browsing.',
  'app.ln3.2901304ad2a8': 'Safari is Apple’s web browser. Leopard ships with Safari 3, based on the WebKit engine.',
  'app.ln3.38c7ff950bcd': 'Dashboard is the Mac OS X widget layer, showing weather, calculator, clock, and more via a hot key.',
  'app.ln3.7ffd2079caca': 'Quartz is macOS 2D drawing and window compositing; Quartz Extreme accelerates compositing with graphics hardware.',
  'app.ln3.c8468a159d79': 'Aqua builds the Mac OS X visual language with translucent materials, gel controls, brushed metal, and continuous animation.',
  'app.ln3.b072ea0a86d6': 'Spotlight searches files, mail, contacts, and apps; in Leopard it also works on network shares.',
  'app.ln3.e4a6fa224098': 'VoiceOver is the built-in Mac OS X screen reader that describes the UI with speech and braille.',
  'app.ln3.71175ed133a7': 'The Leopard Dock uses a reflective 3D shelf and adds Stacks folder piles.',
  'app.ln3.1de0b7b0d534': 'Finder’s Trash holds deleted files so you can restore items or empty it to free virtual storage.',
  'app.ln3.bc14a0242b5d': 'Share photos, presentations, movies, and Quick Look documents in a video chat.',
  'app.ln3.e75720898bce': 'Preview opens PDFs and images with zoom, rotate, inspect, and annotation tools.',
  'app.ln3.092ffe19a1b8': 'The web cannot take over another Mac, but the full invite and status UI is preserved.',
  'app.ln3.ba21304fb20f': 'A bar at the edge of the screen for launching apps, switching windows, and storing items.',
  'app.ln3.64b2ec23a9d9': 'The graphical user interface design language of Mac OS X.',
  'app.ln3.b2c9b796c9a5': 'System-wide metadata search in Mac OS X.',
  'app.ln3.44beedc303bf': 'Cards in the group are kept and moved to the Friends group.',
  'app.ln3.6025af86ea48': 'Hello! This is a local iChat conversation.',
