  'app.ln5.7d3a175887a3': 'No entry in the Apple terms dictionary. Choose a local term on the left such as Finder, Aqua, Dock, Spotlight, Dashboard, Quartz, Safari, or VoiceOver.',
  'app.ln5.176469323382': 'Apple Inc. designs Macs, iPhones, and their operating systems; the Apple menu sits at the far left of the Mac OS X menu bar.',
  'app.ln5.6c1e9973742d': 'In Leopard, Dictionary.app integrates dictionary, thesaurus, Apple terms, and Wikipedia lookup.',
  'app.ln5.f4d316bce86a': 'Leopard Network preferences manage AirPort, Ethernet, Bluetooth, and location profiles.',
  'app.ln5.7d371f966657': 'Finder organizes content on Macintosh HD with files, folders, labels, and metadata.',
  'app.ln5.dcd69c663ade': 'Input volume and levels can be viewed in Sound preferences; the web page needs explicit permission to use the microphone.',
  'app.ln5.a318f32fa19a': 'Mac OS X windows use red, yellow, and green traffic-light buttons to close, minimize, and zoom.',
  'app.ln5.1bfcfafb313a': 'The Macintosh is famous for greeting users with “hello” on screen.',
  'app.ln5.74530a06799a': 'The Mac desktop is managed by Finder and can hold files, disks, and network volumes.',
  'app.ln5.e57b260650b5': 'A reference that lists words by letter or topic and explains meaning, pronunciation, and usage.',
  'app.ln5.2fcfac72d729': 'Allow camera access in the browser address bar, then click the camera button again.',
